from modular.MDTree import modular_decomposition

import networkx as nx
import sys

def getEdgesAdjL(line):

    (nodea, nodesb) = line.split('|')
    nodesb = nodesb.split(',')
    edges = [(nodea, nodeb) for nodeb in nodesb]
    return edges


def readAdjFile(F):
    Gp = nx.Graph()
    l = F.split('\n')
    for line in l:
        (a,b) = line.split('|')
        if (b==''):
            Gp.add_node(a)
        else:
            edges = getEdgesAdjL(line)
            Gp.add_edges_from(edges)
    return Gp

